const c=[{id:"meaning-frankl",title:"M17 · Instituto Viktor Frankl de América · El sentido desde la logoterapia",url:"https://viktorfranklamerica.com/meaning-from-a-logotherapy-perspective/",type:"guidance",finding:"Frankl describió caminos hacia el sentido: crear o hacer, vivir experiencias o amar, y adoptar, si se desea, una postura ante el sufrimiento inevitable.",limitation:"Planteamiento filosófico y clínico, no un ensayo. No necesitas sufrir, y esta reflexión no demuestra efectos de tratamiento."},{id:"meaning-frankl-history",title:"M18 · Instituto Viktor Frankl de Viena · Biografía",url:"https://www.viktorfrankl.org/biography.html",type:"guidance",finding:"Frankl desarrolló la logoterapia antes de su encarcelamiento por los nazis. La biografía institucional documenta su vida y obra.",limitation:"Una experiencia histórica no demuestra la eficacia de una intervención psicológica ni te obliga a encontrar sentido en el sufrimiento."},{id:"meaning-act-values",title:"M19 · Asociación para la Ciencia Conductual Contextual · Seis procesos centrales de ACT",url:"https://contextualscience.org/six_core_processes_act",type:"guidance",finding:"En ACT, los valores son formas de actuar que se mantienen en el tiempo. La acción comprometida los vincula con metas concretas.",limitation:"Orientación sobre un modelo profesional, no un experimento. La brújula y las acciones breves de ODA son adaptaciones sin puntuación validada ni efecto aislado demostrado."},{id:"meaning-act-trials",title:"M04 · A-Tjak y colaboradores · 2015 · Metaanálisis de ACT",url:"https://doi.org/10.1159/000365764",type:"research",finding:"39 ensayos aleatorizados con 1,821 personas probaron programas completos de ACT para problemas mentales o físicos de relevancia clínica.",limitation:"La evidencia de programas clínicos no aísla ejercicios de valores, valida este curso ni establece superioridad frente a la terapia cognitivo conductual consolidada."},{id:"meaning-sdt",title:"M05 · Ryan y Deci · 2000 · Teoría de la autodeterminación",url:"https://selfdeterminationtheory.org/SDT/documents/2000_RyanDeci_SDT.pdf",type:"research",finding:"La teoría distingue actuar por razones que haces tuyas de actuar por presión. Puedes hacer tuyas algunas responsabilidades que inicialmente vienen de otros.",limitation:"Artículo teórico, no una prueba de motivos. La culpa, el placer, la energía corporal o que otros lo noten no determinan si un valor es auténtico."},{id:"meaning-sdt-interventions",title:"M06 · Ntoumanis y colaboradores · 2021 · Intervenciones de motivación en salud",url:"https://eprints.whiterose.ac.uk/id/eprint/155741/",type:"research",finding:"73 estudios de intervenciones de salud con 30,088 participantes encontraron mejoras promedio en motivación autónoma y conductas de salud. Los efectos fueron diversos.",limitation:"58 estudios aleatorizados y 15 cuasiexperimentales usaron programas variados con apoyo. Un ejercicio breve sobre valores no es la intervención estudiada."},{id:"meaning-support",title:"M20 · Instituto Nacional de la Salud Mental · Depresión",url:"https://www.nimh.nih.gov/health/publications/depression",type:"guidance",finding:"El ánimo bajo, la desesperanza, la pérdida de interés o las dificultades para desenvolverte, si persisten, merecen evaluación y apoyo profesional. En EE. UU., el 988 ofrece apoyo en crisis.",limitation:"Perder el sentido por sí solo no diagnostica depresión. ODA ofrece apoyo educativo y no puede tratar la depresión ni atender una crisis aguda."},{id:"meaning-carrillo",title:"M09 · Carrillo y colaboradores · 2019 · Metaanálisis del mejor yo posible",url:"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0222386",type:"research",finding:"29 estudios con 2,909 participantes respaldaron mejoras promedio en bienestar, emociones positivas y optimismo. No se establecieron reducciones de emociones negativas ni de depresión.",limitation:"Los intervalos de confianza de ambos resultados incluyeron cero; solo tres estudios midieron depresión. Métodos variados, principalmente a corto plazo. No se estableció más sentido ni logros futuros."},{id:"meaning-best-possible-self",title:"M10 · King · 2001 · Escribir sobre metas de vida",url:"https://doi.org/10.1177/0146167201277003",type:"research",finding:"81 universitarios fueron asignados al azar a cuatro condiciones de escritura. La tarea sobre el futuro duraba 20 minutos en cada uno de cuatro días consecutivos.",limitation:"La tarea original no probó esta adaptación breve de ODA vinculada a valores. No estableció más sentido, prevención de enfermedades ni logro real de ese futuro."},{id:"meaning-planning",title:"M11 · Gollwitzer y Sheeran · 2006 · Planes si-entonces",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"94 pruebas independientes con 8,461 participantes respaldaron beneficios promedio para alcanzar metas mediante planes que unen una situación concreta y una respuesta prevista.",limitation:"Incluyó pruebas experimentales y correlacionales en contextos distintos. Planear no es actuar. La revisión no estableció más sentido ni la eficacia de este conjunto de pasos de ODA."},{id:"meaning-mental-contrasting",title:"M13 · Wang, Wang y Gai · 2021 · Contraste mental y planificación",url:"https://www.frontiersin.org/articles/10.3389/fpsyg.2021.565202/pdf",type:"research",finding:"24 estudios independientes de 21 artículos, con 15,907 participantes, encontraron un efecto promedio modesto sobre el logro de metas: g = 0.336 [0.229, 0.443].",limitation:"El sesgo de publicación y los formatos diversos limitan la precisión. No se probó combinar valores, una escena futura y acción como aquí. Los obstáculos estructurales no son fallas personales."},{id:"meaning-monitoring",title:"M14 · Harkin y colaboradores · 2016 · Seguimiento del progreso",url:"https://eprints.whiterose.ac.uk/id/eprint/87431/1/bul%20harkin%20raw%20final.pdf",type:"research",finding:"138 estudios aleatorizados encontraron beneficios promedio para alcanzar metas al aumentar el seguimiento: d = 0.40 [0.32, 0.48].",limitation:"Se detectó asimetría en estudios pequeños; un análisis de sensibilidad estimó d = 0.19. Metas y métodos diversos no validan revisar al día siguiente en ODA, efectos sobre el sentido ni seguimiento público obligatorio."},{id:"meaning-habits",title:"M15 · Lally y colaboradores · 2010 · Formación de hábitos",url:"https://doi.org/10.1002/ejsp.674",type:"research",finding:"Un estudio observacional de 84 días siguió a 96 participantes. La automaticidad estimada creció a ritmos distintos; perder una ocasión tuvo poco impacto medido.",limitation:"La mediana de 66 días y el rango de 18–254 días son estimaciones modeladas; las mayores se extrapolaron. No son plazos ni evidencia sobre ausencias repetidas o valores que se vuelven automáticos."}],s=[{schemaVersion:2,revision:2,id:"meaning-1",courseId:"meaning",locale:"es",title:"Toda la semana ocupado. ¿Qué te importó?",goal:"Haz hoy algo útil por una relación o contribución que tú elijas.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"¿Otra semana entre trabajo, pendientes y el celular? Dale tiempo de verdad a algo que te importa.",reason:{id:"meaning-1-reason-attention-cost",label:"¿Qué actividad opcional dejarías para después para dedicar dos minutos a este rumbo?",kind:"text",maxLength:160,optional:!0,suggestions:["Dejar las redes para después","Mover un pendiente no urgente","Abrir un momento para conectar"]},why:{id:"meaning-1-why",label:"¿Qué merece tu atención esta semana?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["No necesitas descubrir un gran propósito antes de hacer algo que te importa. La filosofía de Frankl propone varios caminos: crear o hacer, vivir experiencias o amar, y tomar una postura ante dificultades inevitables. Son invitaciones para pensar, no una prueba ni un tratamiento demostrado. Puedes dejar fuera las dificultades.","Elige una contribución o relación para la prueba que seguirás durante este curso. Dedícale una acción pequeña, busca un momento real y anota después qué pasó. Preguntar y escuchar es actuar. Hacer una lista de personas importantes es prepararte. Tu ánimo puede seguir igual; mira qué hiciste."],example:{title:"La pregunta de Tomás durante la cena",text:"En la cena del martes, Tomás nota que casi no ha escuchado a su hija esta semana. Guarda el celular, pregunta por su proyecto de ciencias y escucha. Ella responde dos frases breves antes de salir. Él anota que preguntó y prestó atención. La charla fue corta, pero sí ocurrió."}},move:{invitation:"Haz algo útil por la relación o contribución que elegiste.",instructions:["Elige un rumbo que mantendrás durante este curso.","Haz algo pequeño y luego anota qué pasó."],prompts:[],suggestions:{action:["Preguntar y escuchar sin mirar el celular","Terminar una frase útil de mi proyecto","Ofrecer una ayuda concreta"],minimum:["Hacer una pregunta y escuchar","Escribir una frase que sirva","Hacer un ofrecimiento concreto"],cue:["Al sentarnos después de cenar","Al abrir mi proyecto","En mi próxima charla segura"],place:["En la mesa de la cocina","En mi mesa habitual de trabajo","En una conversación segura por mensaje"],minutes:[2,5],fallback:["Usar un audio o mensaje seguro","Elegir otro momento disponible","Pedir apoyo práctico"],observation:["Lo que pregunté y escuché","La frase útil que escribí","Si hice el ofrecimiento"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1}]},suggested:{action:"Preguntar y escuchar sin mirar el celular",minimum:"Hacer una pregunta y escuchar",minutes:2,cueHint:"Al sentarnos después de cenar",placeHint:"En la mesa de la cocina",obstacleHint:"La persona no está disponible o pierdo la atención.",fallbackHint:"Usar un audio o mensaje seguro",observationHint:"Lo que pregunté y escuché"},stopRule:"Elige una interacción segura y deseada. Ayudar debe encajar con tus recursos y límites.",accessibleAlternative:"Usa tu forma habitual de comunicarte, contribuye con asistencia o crea algo en privado."},result:{question:"¿Llegaste a hacer la acción que elegiste?",observationPrompt:"¿Qué aportaste, preguntaste o escuchaste?"},judgment:{primary:{id:"meaning-1-dinner-opening-decision",scenario:"Tomás eligió escuchar hoy sobre el proyecto de su hija. Ella tiene cinco minutos antes de salir. Los platos de la cena pueden esperar; él también quiere preparar una buena pregunta.",question:"¿Cómo aprovecha este momento para lo que eligió?",options:[{id:"listen-now",text:"Preguntar ahora por el proyecto y escuchar, luego anotar lo que pasó.",feedback:"Aprovecha el momento para la conversación atenta que eligió. La respuesta puede ser breve o distraída. Los platos y más preparación pueden esperar; eso no significa que conectar deba ser la prioridad de todos."},{id:"meaning-1-share-chore",text:"Lavar juntos los platos durante esos cinco minutos y preguntar por el proyecto mientras recogen la mesa.",feedback:"Una tarea compartida puede acercarlos. Aquí Tomás eligió escuchar con atención y los platos pueden esperar. Dale espacio a una charla breve sin dividir la atención, salvo que ambos prefieran la tarea compartida."},{id:"meaning-1-prepare-question",text:"Usar los cinco minutos para preparar una buena pregunta y enviársela después de que salga.",feedback:"Preparar una pregunta puede facilitar otra charla. Aquí ella está disponible y él ya conoce el tema. Pregunta ahora; si ella decide no conversar, anota que no hubo ocasión."}],bestOptionId:"listen-now"}},carry:{takeaway:"Dale tiempo a lo que te importa y vuelve con los hechos.",followUp:{questionId:"meaning-1-return",question:"¿Qué pasó cuando llegó el momento que elegiste?",observationPrompt:"¿Qué hiciste y estuvo disponible ese momento?",adjustmentPrompt:"¿Qué moverías o cambiarías para la próxima ocasión?"}},goDeeper:{sections:[{heading:"Una filosofía con varios caminos",paragraphs:["Los tres caminos de Frankl vienen de un planteamiento filosófico y clínico. No son una lista que todos deban completar. Crear puede ser hacer un trabajo útil o una buena acción. Vivir experiencias puede ser apreciar algo bello o atender una relación. Adoptar una postura ante el sufrimiento inevitable es otra posibilidad, nunca una obligación. Puedes elegir aportar o conectar sin contar algo doloroso. El Instituto Frankl de América describe estos caminos [M17].","La biografía del instituto de Viena documenta que Frankl desarrollaba la logoterapia antes de su encarcelamiento por los nazis [M18]. Lo que vivió después forma parte de su historia; no demuestra que una lección breve trate el malestar. Este curso toma preguntas de esa filosofía y deja las respuestas en tus manos. Aunque no aparezca una gran respuesta, puedes hacer algo pequeño. Una pregunta atenta, un párrafo útil o una oferta de ayuda con límites permiten observar qué hiciste por el rumbo que elegiste."]},{heading:"De darte cuenta a aprovechar un momento",paragraphs:["Un plan que parece significativo y una acción hecha son registros distintos. La investigación sobre planificación respalda definir una ocasión y una respuesta: cuando ocurra una situación reconocible, haz lo que te propones. Gollwitzer y Sheeran reunieron 94 pruebas independientes con 8,461 participantes [M11]. El logro de metas mejoró en promedio, pero las poblaciones, metas y diseños fueron distintos. Eso no establece que planear aumente el sentido ni que funcione combinar esta filosofía y las acciones del curso.","La adaptación de ODA te permite elegir un rumbo, una acción y un mínimo viable. Que ese primer paso sirva: escuchar una respuesta ayuda a conectar; abrir la lista de contactos solo te prepara. Si el momento no estuvo disponible, anota que no hubo ocasión. Una cita futura sigue siendo un plan. No tienes que demostrar que la charla te cambió la vida. Lo que pasó te ayuda a elegir después: quizá otro lugar, apoyo o un rumbo distinto encajen mejor contigo."]}],sourceIds:["meaning-frankl","meaning-frankl-history","meaning-planning"]}},{schemaVersion:2,revision:2,id:"meaning-2",courseId:"meaning",locale:"es",title:"¿Lo que importa recibe los minutos que sobran?",goal:"Reserva una acción pequeña para tu rumbo y di qué tendrá que esperar.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Dices que te importa. ¿Le das tiempo o solo lo que sobra después de todo lo demás?",reason:{id:"meaning-2-reason",label:"¿Qué moverás para darle tiempo a este rumbo?",kind:"text",maxLength:160,optional:!0,suggestions:["Mover el rato de redes","Mantener un compromiso más pequeño","Hacer espacio para trabajar con cuidado"]},why:{id:"meaning-2-why",label:"¿Qué moverás para darle tiempo a este rumbo?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Una meta se puede completar, como visitar a alguien el domingo. Un valor es una forma de actuar que quieres mantener, como prestar atención. Esa diferencia viene de un modelo de terapia; no significa que las metas importen menos. No llegar a un destino no decide qué rumbo quieres seguir.","Retoma el rumbo y la acción que estás probando. Mira el próximo rato disponible. Dos cosas valiosas pueden competir por él. Elige un mínimo que sirva y di qué esperará. Esa elección tiene un costo real; no significa que el otro valor desapareció. Haz lo que elegiste antes de juzgarlo."],example:{title:"Tomás hace espacio",text:"El miércoles, Tomás tiene diez minutos antes de una tarea de la casa. Quiere conversar otra vez y también leer. Dedica dos minutos al proyecto de su hija y luego comienza la tarea. Leer espera al jueves. Su hija parece distraída; también lo anota. Eligió algo acotado, sin intentar meterlo todo."}},move:{invitation:"Conserva tu rumbo. Busca un rato viable para la próxima acción.",instructions:["Nombra otro uso que compite por este tiempo.","Elige un mínimo útil y hazlo."],prompts:[],suggestions:{action:["Preguntar y escuchar en el rato reservado","Escribir una frase útil del proyecto","Completar una tarea de cuidado acotada"],minimum:["Escuchar una respuesta","Escribir una frase que sirva","Completar una tarea pequeña acordada"],cue:["Al sentarnos después de cenar","En mi rato reservado al proyecto","Después de una rutina de cuidado"],place:["En la mesa de la cocina","En mi mesa habitual de trabajo","Donde se necesita la tarea"],minutes:[2,5],fallback:["Conversar menos tiempo si está disponible","Reducir la tarea sin quitarle utilidad","Pedir compartir la responsabilidad"],observation:["Lo que hice y lo que esperó","El tiempo que sí usé","Si el mínimo sirvió a mi rumbo"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1}]},suggested:{action:"Preguntar y escuchar en el rato reservado",minimum:"Escuchar una respuesta",minutes:2,cueHint:"Al sentarnos después de cenar",placeHint:"En la mesa de la cocina",obstacleHint:"Dos compromisos valiosos compiten por el mismo rato.",fallbackHint:"Conversar menos tiempo si está disponible",observationHint:"Lo que hice y lo que esperó"},stopRule:"No desplaces cuidados urgentes ni la recuperación que necesitas. Cambia el momento o el tamaño.",accessibleAlternative:"Usa comunicación asistida, una tarea que puedas hacer sentado o apoyo para cuidar ese mismo rumbo."},result:{question:"¿Hiciste el mínimo en el rato que reservaste?",observationPrompt:"¿Qué hiciste y qué dejaste para después?"},judgment:{primary:{id:"meaning-2-chosen-commitment-decision",scenario:"Tomás prometió conversar con atención antes del viaje de su hija. Los diez minutos de hoy son su última ocasión. También valora terminar un capítulo no urgente; una llamada más larga puede esperar a la próxima semana.",question:"¿Qué elección cumple su compromiso en este rato?",options:[{id:"reading-later",text:"Escuchar brevemente ahora y buscar otro rato para leer, aceptando que este tiempo es limitado.",feedback:"Cumple la conversación que eligió mientras tienen la ocasión. Leer sigue importando y puede tener otro rato. La respuesta depende de su compromiso y del momento, no de poner un valor por encima de otro."},{id:"full-both",text:"Intentar terminar el capítulo mientras escucha, para que ninguno de los dos compromisos importantes tenga que esperar.",feedback:"Combinar tareas puede conservar tiempo de lectura, pero divide la atención que prometió. Escucha un poco ahora y mueve la lectura, sin afirmar que caben los dos compromisos completos."},{id:"meaning-2-next-week-call",text:"Leer hoy y acordar una conversación más larga la próxima semana, reservando tiempo propio para cada compromiso.",feedback:"Reservar ratos distintos puede tener sentido, y una llamada larga puede valer la pena. Aun así, pierde la charla antes del viaje que eligió. Cumple algo pequeño ahora; acuerda aparte el seguimiento más largo."}],bestOptionId:"reading-later"}},carry:{takeaway:"Una meta pendiente no borra tu rumbo. Dale una acción viable hoy.",followUp:{questionId:"meaning-2-return",question:"¿El rato reservado sirvió al rumbo que elegiste?",observationPrompt:"¿El mínimo sirvió a tu rumbo y qué tuvo que esperar?",adjustmentPrompt:"¿Mantienes esta elección o cambias el momento o el tamaño?"}},goDeeper:{sections:[{heading:"El rumbo y el destino sirven de formas distintas",paragraphs:["La Asociación para la Ciencia Conductual Contextual describe los valores como formas elegidas de actuar de manera continua. La acción comprometida las conecta con metas concretas [M19]. Prestar atención es un rumbo. Escuchar una respuesta hoy es una acción que puedes completar. Se apoyan entre sí: terminar esa acción no significa terminar de ser atento. Puedes cambiar una meta y conservar el rumbo. Son distinciones del modelo ACT, no categorías universales descubiertas mediante experimentos.","La brújula de ODA es una adaptación educativa: elige un área de tu vida, nombra cómo quieres actuar, considera tus circunstancias y elige algo viable. No tiene un punto de corte validado. No necesitas puntuar todas las áreas ni corregir la mayor diferencia numérica. Si cuidas a alguien, tienes poca energía o un turno rígido, puedes priorizar un ritmo sostenible. Decide con tu semana real qué recibirá tiempo; la brújula no dicta un juicio sobre tu vida."]},{heading:"Una acción breve no es un programa de terapia",paragraphs:["A-Tjak y colaboradores revisaron 39 ensayos aleatorizados con 1,821 personas con problemas mentales o físicos de relevancia clínica [M04]. Probaron programas completos de terapia de aceptación y compromiso, con condiciones y comparaciones distintas. No aislaron una brújula de valores, establecieron el efecto de este ejercicio ni demostraron que ODA ofrezca terapia. Un marco útil puede orientar una elección sin recibir por eso toda la evidencia clínica del programa.","Elegir cuándo actuar tiene respaldo aparte en la investigación sobre planes que unen una señal y una respuesta [M11]. Sentarte después de cenar es más fácil de reconocer que «algún día esta semana». Esa evidencia trata del logro de metas, no de sentirte realizado. Que tu mínimo sirva y que su costo quede claro. Si pospones algo no urgente, define otro momento; no finjas que desapareció el costo. Si el rato afecta cuidados esenciales o tu recuperación, reduce la acción, pide ayuda o busca otra ocasión."]}],sourceIds:["meaning-act-values","meaning-act-trials","meaning-planning"]}},{schemaVersion:2,revision:2,id:"meaning-3",courseId:"meaning",locale:"es",title:"Tu elección también puede costarte",goal:"Actúa por una razón que haces tuya y respeta tus responsabilidades y límites.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"¿Sientes culpa por una elección que te importa? Esa emoción no decide si la elección es tuya.",reason:{id:"meaning-3-reason",label:"¿Qué razón haces tuya y qué necesitas proteger?",kind:"text",maxLength:160,optional:!0,suggestions:["Cuidar a quienes quiero","Cumplir mis responsabilidades económicas","Elegir un compromiso opcional"]},why:{id:"meaning-3-why",label:"¿Qué razón haces tuya y qué necesitas proteger?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Una responsabilidad aprendida en tu familia puede convertirse en algo que tú eliges. La investigación sobre motivación distingue actuar por razones propias de hacerlo por presión. Pero no ofrece una prueba instantánea de autenticidad. Sentir culpa, cansancio o satisfacción te dice algo de tu experiencia. No decide qué valor es tuyo.","Mira el rumbo que ya estás probando. Nombra una razón que sigues haciendo tuya y un límite que debes respetar. Mantén las obligaciones esenciales. Cambia una elección opcional de poco costo y haz la acción útil. Puedes tener motivos mezclados. No necesitas estar completamente seguro antes de empezar."],example:{title:"Tomás conserva una razón propia",text:"El jueves, en la mesa de la cocina, Tomás siente culpa por rechazar una charla laboral opcional. Sigue eligiendo estar presente con su hija y cumple su turno obligatorio. En sus dos minutos pregunta por la maqueta y escucha. Anota la charla y la incomodidad. La razón siguió siendo suya aunque la culpa permaneció."}},move:{invitation:"Pon a prueba una razón propia con la acción pequeña que ya elegiste.",instructions:["Mantén las obligaciones necesarias y nombra una elección opcional de poco costo.","Haz la acción sin exigir sentirte seguro."],prompts:[],suggestions:{action:["Preguntar y escuchar por una razón propia","Hacer un aporte opcional al proyecto","Rechazar una invitación opcional que compite"],minimum:["Escuchar una respuesta","Escribir una frase útil","Decir claramente cuándo no puedo"],cue:["Al sentarnos después de cenar","En mi rato opcional de proyecto","Al recibir la invitación opcional"],place:["En la mesa de la cocina","En mi mesa habitual de trabajo","En una conversación segura por mensaje"],minutes:[2,5],fallback:["Mantener obligaciones y reducir esta acción","Elegir otra opción con menos costo","Pedir apoyo con esta limitación"],observation:["Qué elegí con emociones mezcladas","La razón que sigo haciendo mía","La obligación que protegí"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1}]},suggested:{action:"Preguntar y escuchar por una razón propia",minimum:"Escuchar una respuesta",minutes:2,cueHint:"Al sentarnos después de cenar",placeHint:"En la mesa de la cocina",obstacleHint:"Siento presión y hay responsabilidades que no puedo dejar.",fallbackHint:"Mantener obligaciones y reducir esta acción",observationHint:"Qué elegí con emociones mezcladas"},stopRule:"Evita cambios irreversibles. Protege ingresos esenciales, cuidados, seguridad y apoyo necesario.",accessibleAlternative:"Elige en privado o con asistencia, expresa un límite seguro por escrito o pide apoyo práctico."},result:{question:"¿Llevaste a cabo la acción que habías elegido?",observationPrompt:"¿Qué elegiste y qué responsabilidad lograste proteger?"},judgment:{primary:{id:"meaning-3-elective-cost-decision",scenario:"Tomás valora sus ingresos y la conversación familiar de hoy. La charla para hacer contactos se repite mañana con las mismas personas; faltar hoy no afecta ningún turno pagado. La culpa lo empuja a asistir a todo.",question:"¿Qué elección prueba su razón con un costo manejable?",options:[{id:"meaning-3-attend-and-reschedule",text:"Asistir a la charla de hoy y acordar una conversación familiar después del próximo turno, conservando ambos compromisos.",feedback:"Mover un compromiso puede proteger dos cosas valiosas. Aquí podrá ver mañana a los mismos contactos sin perder ingresos. Aplazar la charla familiar que eligió responde a la presión y desaprovecha una alternativa de menor costo."},{id:"endorsed-choice",text:"Cumplir el turno obligatorio, rechazar el evento opcional de hoy y aprovechar el rato de conversación que valora.",feedback:"Prueba la razón que hace suya, protege los ingresos y conserva los contactos de mañana. La culpa puede seguir. Si el costo profesional fuera distinto, otra elección podría ser adecuada."},{id:"meaning-3-split-evening",text:"Entrar brevemente a la charla y acortar la conversación familiar para que lo vean presente en ambas.",feedback:"Dividir el tiempo puede servir si ambas ocasiones son escasas. Aquí la charla laboral se repite mañana. Dividir hoy mantiene su presencia a costa de la atención elegida; aprovecha en cambio la otra ocasión disponible."}],bestOptionId:"endorsed-choice"}},carry:{takeaway:"Elige una razón propia, respeta sus costos y pruébala con una decisión pequeña.",followUp:{questionId:"meaning-3-return",question:"Después de elegir, ¿sigues haciendo tuya esa razón?",observationPrompt:"¿Qué razón eliges ahora, aunque haya dudas o cambios?",adjustmentPrompt:"¿Mantienes la razón, la revisas o pides apoyo con su costo?"}},goDeeper:{sections:[{heading:"Lo aprendido de otros también puede ser tuyo",paragraphs:["La teoría de la autodeterminación de Ryan y Deci describe cómo los motivos que vienen de otros pueden convertirse en razones propias [M05]. Una responsabilidad familiar puede ser difícil, vincularte con otros y seguir siendo tuya. Disfrutar es una razón posible para actuar; cuidar la seguridad de alguien es otra. Eso no vuelve saludable todo compromiso impuesto. Significa que el origen, la incomodidad o el reconocimiento no deciden por sí solos su autenticidad. Pregunta qué razones eliges hoy y qué presiones limitan esa elección.","Preguntarte si lo harías aunque nadie te viera es una reflexión opcional, no una prueba validada. La culpa no demuestra que un valor sea prestado; la energía corporal tampoco demuestra que sea auténtico. Preguntar por qué te ayuda a pensar, pero no certifica un motivo verdadero. Puedes encontrar razones mezcladas y elegir de forma deliberada. Protege ingresos y cuidados necesarios, reconoce compromisos culturales y prueba una acción opcional y reversible. No necesitas cambiar de profesión, relación ni obligación familiar para terminar la lección."]},{heading:"El apoyo influye en la motivación; el ejercicio tiene límites",paragraphs:["Ntoumanis y colaboradores reunieron 73 estudios de intervenciones de salud con 30,088 participantes [M06]. Los programas respaldaron mejoras promedio en motivación autónoma y conductas de salud, con bastante variación. Incluyeron 58 estudios aleatorizados y 15 cuasiexperimentales. Esa evidencia corresponde a intervenciones de salud con apoyo. No demuestra que tres preguntas descubran un motivo verdadero oculto, que los motivos externos siempre sean dañinos ni que un ejercicio breve de ODA reproduzca los programas.","El modelo ACT también conecta las formas de actuar que eliges mantener con acciones concretas [M19]. Aquí esa conexión es una adaptación de ODA, no un tratamiento combinado probado. Usa el próximo intento para averiguar algo específico: ¿encajó la elección con tus responsabilidades y sigues eligiendo su razón? La incomodidad puede quedar en el registro. Si la presión incluye coacción o peligro, protegerte y pedir apoyo tienen prioridad sobre probar la obediencia. Puedes cambiar el rumbo, mantenerlo en privado o pausar sin explicar tus razones."]}],sourceIds:["meaning-sdt","meaning-sdt-interventions","meaning-act-values"]}},{schemaVersion:2,revision:2,id:"meaning-4",courseId:"meaning",locale:"es",title:"No tienes que sacarle algo bueno al dolor",goal:"Cuida tu rumbo con una petición práctica, un límite o una acción humana.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"¿Intentas darle sentido a este dolor? Empieza por lo que puede aliviar la carga. El sentido puede esperar.",reason:{id:"meaning-4-reason",label:"¿Qué cambio práctico te permitiría sostener este rumbo?",kind:"text",maxLength:160,optional:!0,suggestions:["Compartir una tarea de cuidado","Proteger el descanso que necesito","Pedir apoyo profesional"]},why:{id:"meaning-4-why",label:"¿Qué cambio práctico te permitiría sostener este rumbo?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Un hecho irreversible puede dejar margen para organizarte hoy de otra manera. Una enfermedad merece atención y evaluación; no significa «no hay nada que hacer». Elegir una postura ante el sufrimiento inevitable es una posibilidad filosófica de Frankl. No te obliga a ver el dolor como regalo.","Vuelve a lo que estás probando. Si la carga hace insostenible tu acción, cambia el apoyo que la rodea. Pide ayuda con una tarea, pon un límite seguro o protege el descanso necesario. Eso también puede cuidar tu rumbo. Anota la petición o el cambio real. No necesitas sentir que tiene sentido."],example:{title:"Tomás comparte la carga de cuidado",text:"El viernes, Tomás está agotado de organizar las visitas a su padre. Quiere seguir cuidándolo sin perder todas sus tardes. En la mesa de la cocina le pide a su hermano encargarse del traslado del sábado. Al acostarse todavía no tiene respuesta. Anota la petición. La tristeza sigue y no la convierte en una enseñanza."}},move:{invitation:"Conserva tu rumbo. Cambia una carga para la que haya ayuda.",instructions:["Busca un cambio práctico antes de trabajar tu actitud.","Haz una petición concreta o algo seguro para protegerte."],prompts:[],suggestions:{action:["Pedir ayuda con una tarea de cuidado","Poner un límite seguro de disponibilidad","Solicitar apoyo profesional"],minimum:["Enviar una petición concreta de ayuda","Expresar un límite claro","Contactar a alguien para recibir apoyo"],cue:["Después de cenar, antes de organizar visitas","Al recibir la próxima petición","En el momento elegido para pedir apoyo"],place:["En la mesa de la cocina","En una conversación segura por mensaje","En mi espacio privado accesible"],minutes:[2,5],fallback:["Pedir a otra persona adecuada","Mantener el límite privado y buscar ayuda","Elegir una vía de apoyo accesible"],observation:["Mi petición y cualquier respuesta","La organización práctica que cambié","Si contacté para pedir apoyo"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1}]},suggested:{action:"Pedir ayuda con una tarea de cuidado",minimum:"Enviar una petición concreta de ayuda",minutes:2,cueHint:"Después de cenar, antes de organizar visitas",placeHint:"En la mesa de la cocina",obstacleHint:"La primera persona no puede ayudar o contactarla no es seguro.",fallbackHint:"Pedir a otra persona adecuada",observationHint:"Mi petición y cualquier respuesta"},stopRule:"En EE. UU., llama o escribe al 988; en otros lugares, usa apoyo local en crisis. Ante peligro inmediato, contacta emergencias locales.",accessibleAlternative:"Pide ayuda con asistencia o descansa. Busca apoyo profesional antes si persiste la desesperanza o te cuesta desenvolverte."},result:{question:"¿Hiciste el cambio práctico que elegiste?",observationPrompt:"¿Qué pediste o cambiaste, aunque no hubiera respuesta?"},judgment:{primary:{id:"meaning-4-transport-constraint-decision",scenario:"El traslado médico del sábado deja agotado a Tomás. Su hermano ofreció conducir si le confirma hoy. Puede acortar las visitas, pero el traslado es necesario. El transporte comunitario gratuito no tiene lugar el sábado.",question:"¿Qué organización resuelve la carga actual?",options:[{id:"meaning-4-shorten-visits",text:"Acortar la visita del sábado y seguir conduciendo, para reducir la exigencia sin coordinarse con otra persona.",feedback:"Las visitas más cortas pueden cuidar su energía y ayudar. No cambian el traslado necesario que lo agota. Confirma la oferta disponible y luego decide cuánto tiempo de visita puede sostener."},{id:"meaning-4-community-route",text:"Preguntar al transporte comunitario si se libera un lugar y esperar su respuesta antes de confirmar con su hermano.",feedback:"El transporte comunitario podría servir más adelante. El sábado no tiene lugar confirmado y su hermano necesita respuesta hoy. Asegura la ayuda disponible sin hacerla depender de una cancelación."},{id:"share-task",text:"Pedir a su hermano que haga el traslado y luego elegir una duración de visita que pueda sostener.",feedback:"Usa la oferta disponible para la carga que puede cambiar y mantiene cubierto el traslado médico. Hacer la petición no exige haber recibido acuerdo. Si sigue sin respuesta, anótala así."}],bestOptionId:"share-task"}},carry:{takeaway:"Cambia la ayuda y la organización antes de exigirte una actitud mejor.",followUp:{questionId:"meaning-4-return",question:"¿Qué ayuda o cambio práctico siguió a tu petición?",observationPrompt:"¿Qué respuesta o cambio hubo, incluso si nadie contestó?",adjustmentPrompt:"¿Qué ayuda, límite o descanso encaja con la carga pendiente?"}},goDeeper:{sections:[{heading:"Lo que pasó y lo que aún puede cambiar",paragraphs:["Frankl incluye la posibilidad de adoptar una postura ante el sufrimiento que realmente no puedes evitar [M17]. Es orientación filosófica, no evidencia de que la actitud cure enfermedades o vuelva útil el trauma. Una muerte o un hecho pasado no pueden deshacerse. Los síntomas actuales, tratamientos, apoyo social y organización diaria quizá sí puedan cambiar. No pongas un diagnóstico, el daño de otra persona o la falta de ayuda entre lo inmutable sin considerar apoyos.","El modelo ACT propone formas elegidas de actuar mientras hay emociones difíciles [M19]. No exige que desaparezcan ni que permanezcas en un peligro evitable. Puedes conservar el cuidado como rumbo y cambiar otra visita por una petición de compartir el traslado. Descansar, poner un límite o buscar información pueden ser acciones adecuadas. Son elecciones para evaluar según el contexto, no pruebas de una actitud noble. Puedes dejar sin respuesta la pregunta por el sentido y nunca debes contarle a ODA tu sufrimiento."]},{heading:"El apoyo no espera a que encuentres un propósito",paragraphs:["El Instituto Nacional de la Salud Mental describe síntomas de depresión y opciones de evaluación y tratamiento profesional [M20]. La desesperanza, el ánimo bajo, la pérdida de interés o la dificultad para desenvolverte, si persisten, merecen apoyo. Perder el sentido por sí solo no es un diagnóstico; el curso no puede evaluarlo. Puedes pedir ayuda antes de cualquier umbral de duración. No esperes a terminar las lecciones ni a dar una respuesta sobre valores antes de contactar a un médico o profesional de salud mental.","En Estados Unidos, llama o envía un mensaje al 988 para apoyo ante pensamientos suicidas o una crisis emocional. Ante peligro inmediato, usa emergencias. En otros lugares, usa los recursos locales de crisis o emergencias. En una crisis necesitas ayuda humana, no otro ejercicio de reflexión. Fuera de una crisis, puedes pedir algo pequeño y concreto: ayuda con un cuidado, tiempo para recuperarte o una cita. No recibir respuesta también es un hecho. Si esa vía no está disponible, busca otra adecuada; no lo interpretes como una falla de sentido."]}],sourceIds:["meaning-frankl","meaning-act-values","meaning-support"]}},{schemaVersion:2,revision:2,id:"meaning-5",courseId:"meaning",locale:"es",title:"Tu futuro imaginado necesita una parte real",goal:"Usa una escena futura sencilla para elegir una acción concreta por tu rumbo actual.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Tu futuro se ve claro en tu cabeza. ¿Qué parte existirá en tu semana de verdad?",reason:{id:"meaning-5-reason",label:"¿Qué debe cambiar esta semana para que ese futuro encaje?",kind:"text",maxLength:160,optional:!0,suggestions:["Estar presente para conectar","Crear algo que sirva","Respetar mi presupuesto y energía"]},why:{id:"meaning-5-why",label:"¿Qué debe cambiar esta semana para que ese futuro encaje?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Escribir sobre el futuro tiene respaldo más claro para el optimismo y las emociones positivas que para reducir la depresión o las emociones negativas. No demuestra que esa vida imaginada ocurra. Una escena breve puede prepararte para lo que estás probando. No es evidencia de que ya actuaste.","Si te sirve, imagina un día normal de un futuro cercano. Conserva tu rumbo y elige la próxima parte que puedas ver: una conversación, una frase útil o una petición concreta. Mira el obstáculo y tus recursos. Haz esa parte. Si imaginar no ayuda, elige directamente la acción."],example:{title:"Un martes común para Tomás",text:"En el desayuno del sábado, Tomás imagina un martes con las tareas de cuidado compartidas y él ayudando en casa. Imaginar es preparación. Lleva una parte a la práctica: escribe una etiqueta clara para la maqueta escolar de su hija. La termina en la mesa de la cocina; al resto de la maqueta todavía le falta trabajo."}},move:{invitation:"Haz hoy una parte de ese futuro con la acción que ya elegiste.",instructions:["Usa una escena breve si te sirve. Es preparación.","Nombra un obstáculo real y haz una parte que aporte."],prompts:[],suggestions:{action:["Escribir una frase útil del proyecto","Hacer un boceto útil del proyecto","Enviar una petición de comentarios pertinentes"],minimum:["Escribir una frase que sirva","Dibujar un esquema que sirva","Enviar una pregunta concreta sobre mi trabajo"],cue:["Al abrir mi proyecto","Cuando el proyecto necesite un esquema","En mi rato reservado de trabajo"],place:["En mi mesa habitual de trabajo","En la mesa de la cocina","En una conversación segura por mensaje"],minutes:[2,5],fallback:["Elegir un aporte menor que sirva","Usar una descripción escrita","Pedir ayuda para acceder"],observation:["La parte que sí aporté","Lo que cambió el obstáculo","Mi petición y cualquier respuesta"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1}]},suggested:{action:"Escribir una frase útil del proyecto",minimum:"Escribir una frase que sirva",minutes:2,cueHint:"Al abrir mi proyecto",placeHint:"En mi mesa habitual de trabajo",obstacleHint:"Lo que imaginé supera los recursos que tengo disponibles.",fallbackHint:"Elegir un aporte menor que sirva",observationHint:"La parte que sí aporté"},stopRule:"Imagina un futuro sencillo y seguro. Omite las imágenes si aumenta el malestar; evita compromisos costosos.",accessibleAlternative:"Elige directamente qué hacer, usa palabras en vez de imágenes o aporta con asistencia."},result:{question:"¿Creaste la parte que elegiste?",observationPrompt:"¿Qué existió o pasó después de tu intento?"},judgment:{primary:{id:"meaning-5-feedback-opening-decision",scenario:"Una diseñadora tiene una muestra terminada y una colega puede comentarla hoy por la noche. Busca un futuro de trabajo compartido. La próxima semana podrá pedir prestado mejor equipo, pero esta muestra no lo necesita.",question:"¿Qué paso prueba ese rumbo con los recursos actuales?",options:[{id:"meaning-5-prepare-presentation",text:"Dedicar esta noche a mejorar la presentación de la muestra y pedir comentarios cuando la colega vuelva a estar disponible.",feedback:"Una presentación mejor puede aclarar una muestra. Esta ya está terminada y la ocasión de recibir comentarios es hoy. Envía una pregunta concreta; usa la respuesta para decidir si necesita mejor presentación."},{id:"share-sample",text:"Cuidar el presupuesto y enviar la muestra existente con una pregunta concreta para recibir comentarios.",feedback:"Prueba una conducta pertinente con los recursos actuales. Escribir sobre el futuro y alcanzar una meta son resultados distintos. Una respuesta imperfecta también aporta información para el próximo intento."},{id:"meaning-5-borrow-equipment",text:"Esperar al equipo prestado de la próxima semana y hacer una muestra mejor antes de pedir comentarios.",feedback:"Pedir prestado puede proteger el presupuesto cuando necesitas equipo. Esta muestra no lo necesita y la colega está disponible hoy. Prueba el trabajo compartido con lo existente antes de aumentar los requisitos."}],bestOptionId:"share-sample"}},carry:{takeaway:"Imaginar es prepararte. Haz hoy una parte real que sirva a ese rumbo.",followUp:{questionId:"meaning-5-return",question:"¿Lo que hiciste conectó la escena futura con esta semana?",observationPrompt:"¿Qué parte existió y cómo sirvió a tu rumbo?",adjustmentPrompt:"¿Qué recurso u obstáculo debe atender la próxima parte?"}},goDeeper:{sections:[{heading:"Qué ha demostrado escribir sobre el futuro",paragraphs:["Carrillo y colaboradores combinaron 29 estudios con 2,909 participantes [M09]. Los resultados reunidos respaldaron mejoras promedio en bienestar, optimismo y emociones positivas. No se establecieron reducciones de emociones negativas ni de síntomas depresivos. Sus intervalos de confianza incluyeron cero y solo tres estudios evaluaron depresión. Un promedio que parece positivo no resuelve una estimación incierta. Los estudios midieron sobre todo resultados a corto plazo, con métodos de escritura variados. No establecieron más sentido ni logros futuros reales.","La tarea original de King pedía escribir sobre el futuro 20 minutos en cada uno de cuatro días consecutivos. Participaron 81 universitarios asignados al azar a cuatro condiciones de escritura [M10]. La escena breve, cercana y ligada a valores de aquí cambia la duración y el propósito. Es una adaptación de ODA, no el procedimiento original. Escribir más, si quieres, necesita su propio tiempo. No debes describir una vida ideal a cinco años ni compararte con ella. Una posibilidad cotidiana puede bastar para elegir la próxima acción práctica."]},{heading:"Mira también el obstáculo presente",paragraphs:["El contraste mental con planes si-entonces une un deseo viable, el resultado buscado, un obstáculo presente y una respuesta. Wang y colaboradores revisaron 24 estudios independientes de 21 artículos, con 15,907 participantes [M13]. El efecto promedio sobre el logro de metas fue modesto: g = 0.336, con un intervalo de confianza del 95% de 0.229 a 0.443. El ajuste por sesgo de publicación dio una estimación menor. Los formatos y la calidad diversos limitan la certeza. No hay una duración universal de sesión demostrada.","Este curso combina una escena futura con tu rumbo actual y una acción concreta. Ese conjunto no se ha probado. La falta de recursos, cuidar a alguien o un entorno inseguro son limitaciones reales, no debilidades internas. Una respuesta práctica puede ser crear algo más pequeño que sirva, pedir ayuda o elegir otra ocasión. Anota lo que creaste o la interacción aparte de la escena. Si imaginar el futuro añade presión o malestar, omítelo y sigue con una acción elegida directamente."]}],sourceIds:["meaning-carrillo","meaning-best-possible-self","meaning-mental-contrasting"]}},{schemaVersion:2,revision:2,id:"meaning-6",courseId:"meaning",locale:"es",title:"¿Otro plan pendiente? Conserva lo que funcionó",goal:"Usa tus registros para repetir, adaptar o dejar una prueba ligada a tus valores la próxima semana.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"¿Otro plan que no hiciste? Mira tus intentos reales y elige lo que sigue.",reason:{id:"meaning-6-reason",label:"¿Qué acción merece otro lugar en tu semana real?",kind:"text",maxLength:160,optional:!0,suggestions:["Mantener una acción pequeña útil","Cambiar la señal que falló","Cuidar un rumbo sostenible"]},why:{id:"meaning-6-why",label:"¿Qué acción merece otro lugar en tu semana real?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Planear y actuar son cosas distintas. La investigación respalda, en promedio, los planes ligados a señales y el seguimiento del progreso para alcanzar metas. Ninguno demuestra que actuar a diario aumente el sentido. Separa lo que pasó de cómo te sentiste.","Revisa tu rumbo y tus registros. ¿Qué ocasión ocurrió? ¿Qué mínimo cumplió su propósito? Elige qué repetir o cambiar la próxima semana. Conserva lo útil; deja rituales extra. Perder una ocasión aporta información; no fija un plazo de hábito ni juzga tus valores. Pedir apoyo, descansar y dejar un plan dañino siguen siendo opciones."],example:{title:"Tomás planea con sus registros",text:"El domingo, en la mesa de la cocina, Tomás ve dos charlas, una ocasión que no ocurrió y una petición de ayuda sin respuesta. Dos minutos después de cenar funcionaron mejor que más tarde. Pregunta otra vez por la maqueta y escucha. Mantiene esa señal la próxima semana; pedirá apoyo de nuevo si las visitas la desplazan."}},move:{invitation:"Usa tus registros. Conserva una acción útil para la próxima semana.",instructions:["Compara las ocasiones y los mínimos que sí probaste.","Cambia una condición y haz el próximo intento."],prompts:[],suggestions:{action:["Repetir la escucha que sirvió","Repetir mi aporte útil al proyecto","Pedir el apoyo que sugieren mis registros"],minimum:["Escuchar una respuesta","Escribir una frase que sirva","Enviar una petición concreta de apoyo"],cue:["Al sentarnos después de cenar","En la señal de proyecto ya probada","Antes de organizar el próximo cuidado"],place:["En la mesa de la cocina","En mi mesa habitual de trabajo","En una conversación segura por mensaje"],minutes:[2,5],fallback:["Usar mi versión pequeña ya probada","Elegir otro momento realista","Buscar apoyo o pausar este plan"],observation:["Lo que hice y si apareció la señal","Qué permitió la condición que cambié","Si el mínimo aún sirvió a mi rumbo"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1}]},suggested:{action:"Repetir la escucha que sirvió",minimum:"Escuchar una respuesta",minutes:2,cueHint:"Al sentarnos después de cenar",placeHint:"En la mesa de la cocina",obstacleHint:"El horario anterior ya no encaja con mis responsabilidades.",fallbackHint:"Usar mi versión pequeña ya probada",observationHint:"Lo que hice y si apareció la señal"},stopRule:"Cambia o deja planes que afecten tu seguridad, los cuidados o la recuperación necesaria.",accessibleAlternative:"Mantén una acción accesible, pide apoyo o elige descansar sin añadir otro ritual."},result:{question:"¿Hiciste el siguiente mínimo que habías elegido?",observationPrompt:"¿Qué hiciste realmente? ¿Apareció la señal que elegiste?"},judgment:{primary:{id:"meaning-6-tested-opening-decision",scenario:"El horario nocturno de Tomás falló dos veces porque las visitas se alargaron. La cena permitió dos charlas breves. No sabe si tendrá tiempo el fin de semana. Quiere mantener el contacto la próxima semana y puede volver a usar la cena.",question:"¿Qué plan aprovecha mejor estos registros?",options:[{id:"meaning-6-earlier-night",text:"Adelantar treinta minutos la charla nocturna, para conservar una conversación más larga y sin interrupciones.",feedback:"Adelantarla podría conservar una charla larga. Los registros siguen mostrando visitas que se alargan; no demuestran que moverla así evite el problema. Prueba la ocasión de la cena que ya permitió el contacto."},{id:"meaning-6-weekend-conversation",text:"Reservar una charla más larga el fin de semana para que las visitas entre semana ya no compitan con ella.",feedback:"Una charla de fin de semana puede valer la pena si acuerdan cuándo. Aquí no hay disponibilidad segura. Mantén el mínimo probado de la cena y organiza algo más largo cuando haya una ocasión real."},{id:"tested-cue",text:"Conservar el contacto, usar el mínimo de la cena y anotar el próximo intento antes de cambiar otra cosa.",feedback:"Repite una ocasión que permitió la acción elegida. No garantiza otra charla. Anota si apareció la señal y qué pasó; luego decide si hace falta más apoyo o un cambio."}],bestOptionId:"tested-cue"}},carry:{takeaway:"Mantén un rumbo, una acción útil y un registro que mejore el siguiente intento.",followUp:{questionId:"meaning-6-return",question:"¿La condición elegida con tus registros ayudó a la siguiente acción?",observationPrompt:"¿Apareció la señal y qué permitió esa condición?",adjustmentPrompt:"¿Repites la condición, la cambias, buscas apoyo o paras?"}},goDeeper:{sections:[{heading:"Planear y revisar ayudan a observar la conducta",paragraphs:["Gollwitzer y Sheeran reunieron 94 pruebas independientes con 8,461 participantes [M11]. Los planes concretos que unen situación y respuesta mejoraron en promedio el logro de metas, con diseños y entornos diversos. Harkin y colaboradores revisaron 138 estudios aleatorizados de seguimiento [M14]. La estimación combinada sobre el logro de metas fue d = 0.40, con un intervalo de confianza del 95% de 0.32 a 0.48. Detectaron asimetría en estudios pequeños; un análisis de sensibilidad estimó d = 0.19. Los resultados tratan del logro de metas, no prometen realización personal.","Estas revisiones no han validado el resumen guardado ni la revisión al día siguiente de ODA. Sirven para comparar un compromiso concreto con un intento real y ajustar lo que sigue. No necesitas compartir el seguimiento. Deja los detalles sensibles fuera de ODA si prefieres. Un plan futuro sigue siendo un plan. Si no hay registro, lo ocurrido sigue sin saberse. Puedes repetir un mínimo eficaz sin hacerlo más grande. Pedir apoyo práctico o planear descanso puede servir mejor al mismo rumbo que otra tarea exigente."]},{heading:"Una estimación de hábito no es una fecha límite",paragraphs:["Lally y colaboradores siguieron a 96 participantes en un estudio observacional de 84 días [M15]. Cada persona eligió conductas de comida, bebida o actividad con señales diarias. La automaticidad modelada creció a ritmos muy distintos. La conocida mediana de 66 días y el rango de 18–254 días son estimaciones ajustadas; las mayores se extienden más allá de lo observado. No son plazos para tu acción ni demuestran que los valores se vuelvan automáticos o que faltar varios días no afecte. Perder una ocasión tuvo poco impacto medido en ese estudio.","Tu prueba usa una acción no alimentaria ligada a valores y una revisión al día siguiente. Es una adaptación, no el procedimiento del estudio. Conserva lo respaldado por tus registros: una señal viable, un mínimo útil y una respuesta al obstáculo real. Deja un ejercicio que no ayudó. No compenses una semana interrumpida duplicando todas las exigencias. Elige la siguiente ocasión posible, pide apoyo si lo necesitas y conserva lo que pasó en tus registros cuando cambies el plan."]}],sourceIds:["meaning-planning","meaning-monitoring","meaning-habits"]}}],u=[{id:"meaning-1",practice:["Elige una contribución o relación; pensar sobre dificultades es opcional.","Nombra una acción útil y una ocasión segura.","Haz lo que elegiste y anota qué pasó."],correct:1,photo:{id:"1469474968028-56623f02e42e",alt:"Una figura solitaria sobre una roca, encima de un valle con niebla"}},{id:"meaning-2",practice:["Retoma el rumbo y la acción que elegiste.","Reserva un rato viable diciendo qué tarea no urgente tendrá que esperar.","Haz el mínimo útil y anota qué esperó."],correct:2,photo:{id:"1470071459604-3b5ec3a7fe05",alt:"Nubes sobre acantilados verdes y un valle"}},{id:"meaning-3",practice:["Nombra una razón propia y permite motivos mezclados.","Protege las obligaciones necesarias y elige un cambio opcional y reversible con su costo.","Haz la acción y anota tu elección sin puntuar la culpa."],correct:0,photo:{id:"1447752875215-b2761acb3c5d",alt:"Un puente peatonal de madera en un bosque verde"}},{id:"meaning-4",practice:["Mira qué ayuda práctica o protección es posible.","Elige una petición concreta, un límite seguro o el descanso necesario.","Haz lo que elegiste sin exigirle sentido ni algo bueno al dolor."],correct:2,photo:{id:"1519681393784-d120267933ba",alt:"Estrellas sobre montañas nevadas de noche"}},{id:"meaning-5",practice:["Si quieres, imagina una escena sencilla del futuro cercano. Es preparación, no el método original de escritura.","Nombra un obstáculo real y una respuesta viable.","Haz una parte pertinente y anótala aparte de la escena."],correct:1,photo:{id:"1501785888041-af3ef285b470",alt:"Un lago tranquilo rodeado de montañas"}},{id:"meaning-6",practice:["Compara los intentos reales por tu rumbo actual.","Elige una condición para repetir o cambiar la próxima semana.","Prueba el mínimo útil y anota la señal y la acción."],correct:1,photo:{id:"1472214103451-9374bd1c798e",alt:"Una pradera verde con árboles bajo una luz suave"}}],l={id:"meaning",title:"¿Mil pendientes? Dale tiempo a lo que importa",subtitle:"6 lecciones para llevar un rumbo que valoras a acciones reales, registros honestos y una próxima semana viable.",description:"Elige una contribución o relación que merezca tu atención. Prueba una acción pequeña, reconoce su costo y ajusta según lo que pase.",scope:"Para adultos que tienen mil pendientes y poco rumbo, están ante una decisión o quieren que sus días reflejen lo que les importa. Es educación y reflexión personal, no terapia ni tratamiento. Si el vacío o la desesperanza persisten o te cuesta desenvolverte a diario, habla con un médico o profesional de salud mental. Puedes pedir apoyo antes. Ante pensamientos suicidas o una crisis emocional en EE. UU., llama o escribe al 988; en otros lugares, usa apoyo local de crisis. Ante peligro inmediato, contacta emergencias locales.",outcome:"Una prueba ligada a valores con registros de intentos reales y un plan para la próxima semana que respete tus responsabilidades.",photo:{id:"1500530855697-b586d89ba3ee",alt:"Un camino entre colinas abiertas que avanza hacia el horizonte"},lang:"es",lessons:s.map((e,t)=>{const i=u[t],a=e.judgment.primary,n=a.options.find(o=>o.id===a.bestOptionId),r=a.options.filter(o=>o.id!==a.bestOptionId).map(o=>o.text);return r.splice(i.correct,0,n.text),{...i,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,deeper:e.goDeeper.sections,example:e.idea.example,reflection:e.direction.reason.label,question:`${a.scenario} ${a.question}`,options:r,feedback:n.feedback,takeaway:e.carry.takeaway,sources:e.goDeeper.sourceIds}})},d=Object.freeze(Object.defineProperty({__proto__:null,COURSE:l,MEANING_LESSONS_V2:s,SOURCES:c},Symbol.toStringTag,{value:"Module"}));export{d as m};
